function applyMechanicFormat(format, value) {
  return String(format || '').replace(/\{value\}/g, String(value));
}

function authoredMechanic(format, value, fallbackContext) {
  if (typeof format === 'string') {
    return { context: fallbackContext, text: applyMechanicFormat(format, value) };
  }
  if (!format || typeof format !== 'object') return null;
  const text = applyMechanicFormat(format.format, value);
  const context = String(format.context || fallbackContext).trim();
  return context && text ? { context, text } : null;
}

function abilityDisplayValues(ability) {
  const values = {};
  const effects = Array.isArray(ability?.effects) ? ability.effects : [];
  const firstEffect = effects[0];
  if (firstEffect?.turnsLeft != null && firstEffect.turnsLeft !== Infinity) {
    values.duration = firstEffect.turnsLeft;
  }
  for (const effect of effects) {
    const definition = getEffectDefinition(effect?.key);
    if (definition?.maxStacks != null) values['effect.maxStacks'] = definition.maxStacks;
    for (const operation of definition?.periodic || []) {
      const prefix = `effect.${operation.operation}`;
      values[`${prefix}.amount`] = operation.amount;
      values[`${prefix}.interval`] = operation.interval;
      if (operation.damageType) values[`${prefix}.damageType`] = operation.damageType;
    }
  }
  return values;
}

function formatAmmoMechanics(info, mechanicFormats = {}) {
  const mechanics = [];
  const affinities = info?.ammoAffinities && typeof info.ammoAffinities === 'object'
    ? info.ammoAffinities
    : {};
  const authoredAffinities = mechanicFormats?.ammoAffinities && typeof mechanicFormats.ammoAffinities === 'object'
    ? mechanicFormats.ammoAffinities
    : {};
  for (const [ammoId, modifiers] of Object.entries(affinities)) {
    if (!modifiers || typeof modifiers !== 'object') continue;
    const ammoName = humanizeToken(ammoId).replace(/^Ammo\s+/i, '');
    for (const [key, value] of Object.entries(modifiers)) {
      const authoredFormat = authoredAffinities?.[ammoId]?.[key];
      const authored = authoredMechanic(authoredFormat, value, 'Wearing');
      if (authored) {
        mechanics.push(authored);
        continue;
      }
      const text = formatAmmoModifier(key, value);
      if (ammoName && text) mechanics.push({ context: 'Wearing', text });
    }
  }

  const lootBiases = info?.lootBiases && typeof info.lootBiases === 'object'
    ? info.lootBiases
    : {};
  const authoredLootBiases = mechanicFormats?.lootBiases && typeof mechanicFormats.lootBiases === 'object'
    ? mechanicFormats.lootBiases
    : {};
  for (const [lootId, value] of Object.entries(lootBiases)) {
    const multiplier = Number(value);
    if (!Number.isFinite(multiplier) || multiplier <= 0 || multiplier === 1) continue;
    const lootName = humanizeToken(lootId).replace(/\s+Stack$/i, '');
    const authoredFormat = authoredLootBiases?.[lootId];
    const authored = authoredMechanic(authoredFormat, multiplier, 'Loot');
    if (authored) {
      mechanics.push(authored);
      continue;
    }
    mechanics.push({ context: 'Loot', text: `${lootName} appear at ${multiplier}× weighting` });
  }
  return mechanics;
}

function formatProcPackageMechanics(procPackages, mechanicFormats = {}) {
  const formats = mechanicFormats?.procPackages && typeof mechanicFormats.procPackages === 'object'
    ? mechanicFormats.procPackages
    : {};
  const mechanics = [];
  const authoredIds = new Set();
  for (const pkg of procPackages) {
    const formatSpec = formats[pkg?.id] || pkg?.display;
    if (formatSpec == null) continue;
    const format = typeof formatSpec === 'string' ? formatSpec : formatSpec?.format;
    if (typeof format !== 'string' || !format.trim()) continue;
    const parameterValues = {
      ...(formatSpec?.values && typeof formatSpec.values === 'object' ? formatSpec.values : {}),
      ...(pkg?.params && typeof pkg.params === 'object' ? pkg.params : {}),
    };
    const interpolate = (value, values) => String(value || '').replace(/\{([a-zA-Z0-9_.]+)\}/g, (_match, key) => String(values[key] ?? ''));
    const values = {
      ...parameterValues,
      id: String(pkg?.id || ''),
      name: String(pkg?.name || ''),
      summary: interpolate(pkg?.summary, parameterValues),
    };
    const text = interpolate(format, values);
    if (!text.trim()) continue;
    mechanics.push({
      context: typeof formatSpec === 'object' && formatSpec.context
        ? String(formatSpec.context)
        : 'Equip',
      text: text.trim(),
    });
    authoredIds.add(String(pkg?.id || ''));
  }
  return { mechanics, authoredIds };
}

function formatAffixMechanics(affixes, mechanicFormats = {}) {
  const formats = mechanicFormats?.affixes && typeof mechanicFormats.affixes === 'object'
    ? mechanicFormats.affixes
    : {};
  const mechanics = [];
  const authoredIds = new Set();
  for (const affixId of Array.isArray(affixes) ? affixes : []) {
    const key = String(affixId || '');
    const formatSpec = formats[key] || getAffix(key)?.display;
    if (formatSpec == null) continue;
    const format = typeof formatSpec === 'string' ? formatSpec : formatSpec?.format;
    if (typeof format !== 'string' || !format.trim()) continue;
    const values = {
      ...(formatSpec?.values && typeof formatSpec.values === 'object' ? formatSpec.values : {}),
      id: key,
      name: getAffixName(key),
    };
    const text = format.replace(/\{([a-zA-Z0-9_.]+)\}/g, (_match, name) => String(values[name] ?? ''));
    if (!text.trim()) continue;
    mechanics.push({
      context: typeof formatSpec === 'object' && formatSpec.context
        ? String(formatSpec.context)
        : 'Equip',
      text: text.trim(),
    });
    authoredIds.add(key);
  }
  return { mechanics, authoredIds };
}

function formatEventKind(value) {
  const key = String(value || "").trim();
  if (!key) return "On Trigger";
  const map = {
    onBeforeHit: "On Before Hit",
